// Competitor Price Monitor: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

let watch = []; try { watch = $('Watchlist').all().map(i => i.json); } catch (e) { /* sample-data run */ }
const rows = input.map((r, i) => r.html ? r : { ...watch[i], html: r.data || '' });
const extract = (html, sel) => { const [, tag, sep, val] = sel.match(/^(\w+)([.#])?(.*)$/) || [];
  const attr = sep === '#' ? `id=["']${val}["']` : `class=["'](?:[^"']*\\s)?${val}(?:\\s[^"']*)?["']`;
  const m = html.match(new RegExp(`<${tag}[^>]*${val ? attr : ''}[^>]*>([\\s\\S]*?)</${tag}>`, 'i')); return m ? m[1].replace(/<[^>]+>/g, '').trim() : null; };
const out = [];
for (const r of rows) {
  const pt = extract(r.html, r.price_selector), m = pt && pt.replace(/\s/g, '').match(/(\d[\d,]*\.?\d*)/), price = m ? Number(m[1].replace(/,/g, '')) : null;
  const stock = (extract(r.html, r.stock_selector) || '').toLowerCase(), inStock = !/out of stock|sold out/.test(stock), alerts = [];
  if (price && r.last_price && price < r.last_price * 0.95) alerts.push(`${r.store} dropped ${r.product} from ${r.last_price.toLocaleString()} to ${price.toLocaleString()}`);
  if (price && inStock && price < r.my_price) alerts.push(`${r.store} undercuts you on ${r.product}: ${price.toLocaleString()} vs your ${r.my_price.toLocaleString()}`);
  out.push({ route: alerts.length ? 'alert' : 'ok', store: r.store, product: r.product, price, in_stock: inStock, alerts: alerts.join('\n') });
}
return out.map(json => ({ json }));
